                    "text": "約書亞率百姓走乾地過約旦河，繞行耶利哥城七日吹角城牆倒塌",
                    "year": "約 BC 1406",
                    "era": "進取迦南",
                    "note": "約書亞記 3–6 章：喇合全家因窗上朱紅線繩得救。"
