                    "text": "摩押女子路得隨婆婆拿俄米歸回伯利恆，嫁與至親贖買者波阿斯",
                    "year": "約 BC 1100",
                    "era": "路得記時代",
                    "note": "路得記 1–4 章：生下俄備得，成為大衛王的曾祖母。"
