                    "id": "t8_6",
                    "text": "哈拿在示羅會幕禱告求得撒母耳，撒母耳帶領全民在米斯巴悔改立以便以謝石",
                    "year": "約 BC 1080–1050",
                    "era": "士師末期",
                    "note": "撒母耳記上 1–7 章：結束士師時代，開啟君王與先知新紀元。"
